const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto"),assert=require("node:assert/strict");
const d="docs/coordinator/worktree-completion/evidence/",prefix=d+"dcc1-parity-observer-diagnostic-admission";
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const ledgerPath=d+"dcc1-parity-observer-preflight-correction-final-inventory.json",ledgerBytes=fs.readFileSync(ledgerPath);
assert.equal(ledgerBytes.length,119777);assert.equal(sha(ledgerBytes),"39a8dedf4b15a764dd512903342d0e72b40fbc810d1263d692c9b7acc44906ff");
const ledger=JSON.parse(ledgerBytes).record,info=path=>{const s=fs.lstatSync(path),b=fs.readFileSync(path);assert(s.isFile()&&!s.isSymbolicLink());return{path,bytes:b.length,sha256:sha(b),mode:s.mode&4095}};
assert.equal(ledger.untracked.length,277);const self=info(ledgerPath);assert.equal(self.mode,0o644);
const expected=[...ledger.untracked,self];const paths=cp.execFileSync("git",["ls-files","--others","--exclude-standard","-z"],{encoding:"utf8"}).split("\0").filter(Boolean);
assert.deepEqual(paths.sort(),expected.map(x=>x.path).sort());for(const x of expected){const n=info(x.path);for(const k of ["path","bytes","sha256","mode"])assert.equal(n[k],x[k],x.path+" "+k)}
for(const p of [prefix+".raw.log",prefix+".meta.jsonl",d+"dcc1-parity-observer-diagnostic-admission.json",d+"dcc1-parity-observer-diagnostic-command.json",d+"dcc1-parity-observer-diagnostic-postflight.json","docs/coordinator/worktree-completion/reports/dcc1-parity-observer-diagnostic-renewed.md"])assert(!fs.existsSync(p),p+" exists");
const corrected=JSON.parse(fs.readFileSync(d+"dcc1-parity-observer-preflight-correction.json")).correctedCommand;
assert(corrected.startsWith("node <<'NODE'\n")&&corrected.endsWith("\nNODE"));let source=corrected.slice("node <<'NODE'\n".length,-"\nNODE".length);
assert.equal(sha(source),"8f358f85b55dc5e301126c672b9ee8768043abe3283f15cbbe102735214cb194");
const oldBlock='const extra=["docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-proof-final-inventory.json","docs/coordinator/worktree-completion/handoffs/2026-08-30-dcc1-observer-proof-received.md"];\ncheck(untracked.length===268,"268 untracked");\nconst by=new Map(untracked.map(x=>[x.path,x]));for(const x of final.untracked){const now=by.get(x.path);check(now&&now.bytes===x.bytes&&now.sha256===x.sha256&&now.mode===x.mode,"prior untracked "+x.path)}check(untracked.every(x=>final.untracked.some(y=>y.path===x.path)||extra.includes(x.path)),"untracked exact membership");';
const newBlock='const ledgerPath=d+"dcc1-parity-observer-preflight-correction-final-inventory.json",ledgerBytes=fs.readFileSync(ledgerPath);\ncheck(ledgerBytes.length===119777&&sha(ledgerBytes)==="39a8dedf4b15a764dd512903342d0e72b40fbc810d1263d692c9b7acc44906ff","approved ledger bytes");\nconst approved=JSON.parse(ledgerBytes).record.untracked;\ncheck(approved.length===277,"approved 277 records");\nconst expected=[...approved,{path:ledgerPath,bytes:119777,sha256:"39a8dedf4b15a764dd512903342d0e72b40fbc810d1263d692c9b7acc44906ff",mode:420}];\ncheck(untracked.length===278,"278 untracked");\nconst by=new Map(untracked.map(x=>[x.path,x]));for(const x of expected){const now=by.get(x.path);check(now&&now.bytes===x.bytes&&now.sha256===x.sha256&&now.mode===x.mode,"prior untracked "+x.path)}check(untracked.every(x=>expected.some(y=>y.path===x.path)),"untracked exact membership");';
assert.equal(source.split(oldBlock).length,2);source=source.replace(oldBlock,newBlock);
const start=new Date().toISOString(),mono=process.hrtime.bigint(),chunks=[],errors=[];
const child=cp.spawn(process.execPath,[],{cwd:process.cwd(),stdio:["pipe","pipe","pipe"]});
child.stdout.on("data",b=>chunks.push(b));child.stderr.on("data",b=>chunks.push(b));child.on("error",e=>errors.push(String(e)));child.stdin.end(source);
child.on("close",(code,signal)=>{const end=new Date().toISOString(),bytes=Buffer.concat(chunks);let result,parseError;try{result=JSON.parse(bytes.toString("utf8"))}catch(e){parseError=String(e)}
const write=(fd,b)=>{let n=0;while(n<b.length)n+=fs.writeSync(fd,b,n,b.length-n);fs.fsyncSync(fd)};
let loggerExit=0;try{const raw=fs.openSync(prefix+".raw.log","wx",0o600),meta=fs.openSync(prefix+".meta.jsonl","wx",0o600);write(raw,bytes);fs.closeSync(raw);write(meta,Buffer.from(JSON.stringify({event:"start",start,cwd:process.cwd(),pid:child.pid,executable:process.execPath,args:[],stdinSource:source,stdinSourceSha256:sha(source),originalCorrectedSourceSha256:sha(corrected.slice("node <<'NODE'\n".length,-"\nNODE".length)),oldBlock,newBlock,original278ComparedBeforeOutputCreation:true,classification:"Start facts captured before child spawn; metadata and complete raw bytes persisted after child terminal and before transport to preserve exact pre-output membership."})+"\n"));write(meta,Buffer.from(JSON.stringify({event:"terminal",start,end,elapsedSeconds:Number(process.hrtime.bigint()-mono)/1e9,gateExit:code,signal,loggerExit:0,errors,parseError,rawBytes:bytes.length,rawSha256:sha(bytes)})+"\n"));fs.closeSync(meta)}catch(e){loggerExit=1;errors.push(String(e))}
console.log(JSON.stringify({gateExit:code,signal,loggerExit,errors,parseError,rawBytes:bytes.length,rawSha256:sha(bytes),result:result&&{pass:result.pass,failures:result.failures,index:result.index,executionClosure:result.executionClosure,untracked:result.untracked.length,tracked:result.trackedCount,retained:result.retainedCount,preserve:result.preserve.length,commands:result.commands.map(x=>({executable:x.executable,args:x.args,exit:x.exit}))}}));process.exitCode=loggerExit||parseError?2:(code===null?2:code);});

preservation.script:
const fs=require("node:fs"),path=require("node:path"),crypto=require("node:crypto"),assert=require("node:assert/strict");const d="docs/coordinator/worktree-completion/evidence/",root=d+"dcc1-parity-observer-diagnostic-preserved",sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const raw=fs.readFileSync(d+"dcc1-parity-observer-diagnostic-admission.raw.log");assert.equal(sha(raw),"abb4c4b52f084ff249917d407f1622e3b008b5b571384b0bbead66e33fcfce5f");const pre=JSON.parse(raw);assert(pre.pass&&pre.failures.length===0);assert.equal(pre.preserve.length,112);assert(!fs.existsSync(root));
for(const x of pre.preserve){assert(!path.isAbsolute(x.path)&&!x.path.split("/").includes(".."));const b=fs.readFileSync(x.path),s=fs.lstatSync(x.path);assert(s.isFile()&&!s.isSymbolicLink());assert.equal(b.length,x.bytes);assert.equal(sha(b),x.sha256);assert.equal(s.mode&4095,x.mode);}
const startedAt=new Date().toISOString();fs.mkdirSync(root,{mode:0o700});const copies=[];
for(const x of pre.preserve){const target=path.join(root,x.path);fs.mkdirSync(path.dirname(target),{recursive:true,mode:0o700});fs.copyFileSync(x.path,target,fs.constants.COPYFILE_EXCL);fs.chmodSync(target,x.mode);const fd=fs.openSync(target,"r");fs.fsyncSync(fd);fs.closeSync(fd);const b=fs.readFileSync(target),original=fs.readFileSync(x.path),s=fs.lstatSync(target);assert(b.equals(original));assert.equal(sha(b),x.sha256);assert.equal(s.mode&4095,x.mode);copies.push({...x,preservedPath:target,preservedBytes:b.length,preservedSha256:sha(b),preservedMode:s.mode&4095,byteEqual:true});}
const dirs=new Set(copies.map(x=>path.dirname(x.preservedPath)));dirs.add(root);for(const p of dirs){const fd=fs.openSync(p,"r");fs.fsyncSync(fd);fs.closeSync(fd);}
console.log(JSON.stringify({classification:"Exclusive mechanical preservation copies, not new browser captures",startedAt,endedAt:new Date().toISOString(),root,copies,count:copies.length,pass:true}));
